inline void drawButtonFocus(HDC dc,RECT r,HWND control,UINT state){if(!(state&ODS_FOCUS)||!GetPropW(GetAncestor(control,GA_ROOT),L"PixForgeKeyboardFocus"))return;HPEN pen=CreatePen(PS_SOLID,1,RGB(117,112,172));auto oldPen=SelectObject(dc,pen),oldBrush=SelectObject(dc,GetStockObject(NULL_BRUSH));RoundRect(dc,r.left+1,r.top+1,r.right-1,r.bottom-1,6,6);SelectObject(dc,oldBrush);SelectObject(dc,oldPen);DeleteObject(pen);}
inline void drawViewSwitch(HDC dc,RECT r,const std::wstring& label,bool checked,bool enabled,int dpi,COLORREF background=RGB(35,38,46)){
    auto scale=[&](int value){return MulDiv(value,dpi,96);};
    fill(dc,r,background);RECT caption=r;caption.left+=scale(2);caption.right-=scale(36);text(dc,label,caption,enabled?RGB(230,233,241):RGB(110,117,132));
    float width=float(scale(28)),height=float(scale(16)),x=float(r.right-scale(32)),y=(r.bottom-r.top-height)/2.f+r.top;
    Gdiplus::Graphics g(dc);g.SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);Gdiplus::GraphicsPath path;path.AddArc(x,y,height,height,90,180);path.AddArc(x+width-height,y,height,height,270,180);path.CloseFigure();
    Gdiplus::SolidBrush track(enabled?(checked?Gdiplus::Color(255,155,147,255):Gdiplus::Color(255,78,86,103)):Gdiplus::Color(255,55,60,71));g.FillPath(&track,&path);
    float knob=height-scale(4),kx=checked?x+width-knob-scale(2):x+scale(2);Gdiplus::SolidBrush thumb(enabled?Gdiplus::Color(255,250,250,253):Gdiplus::Color(255,139,145,157));g.FillEllipse(&thumb,kx,y+scale(2),knob,knob);

}
inline bool isFormSwitch(HWND h){return GetPropW(h,L"PixForgeSwitch")!=nullptr;}
inline bool formSwitchValue(HWND h){return INT_PTR(GetPropW(h,L"PixForgeSwitch"))==2;}
inline void formSwitchSet(HWND h,bool checked){SetPropW(h,L"PixForgeSwitch",HANDLE(INT_PTR(checked?2:1)));auto label=windowText(h);auto separator=label.find(L"：");if(separator!=std::wstring::npos)label.resize(separator);label+=checked?L"：已开启":L"：已关闭";SetWindowTextW(h,label.c_str());InvalidateRect(h,nullptr,FALSE);}
